namespace local_examtelemetry;

use local_examtelemetry\local\license;

/**
 * Isolated transport for HTTP status tests.
 *
 * @package    local_examtelemetry
 * @copyright  2026 TAG Digital Solutions Ltd <https://tandreig.com>
 * @author     Andrei Toma
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class fake_license extends license {
    /** @var array Fake response. */
    public static $reply = [];

    /**
     * Return a simulated HTTP response.
     *
     * @param string $action Operation
     * @param string $key Key
     * @return array
     */
    protected static function http_post(string $action, string $key): array {
        return self::$reply;
    }
}
